        "welcomeTitle": "미리 보기 버전 안내",
        "welcomeBody": "DeepSeek Harness 0.2는 아직 미리 보기 버전이며, 계속 개선하고 다듬어야 할 부분이 많아요. 모든 개발자와 사용자의 피드백과 제안을 환영해요. 새 데스크톱 앱은 이제 폭넓은 사용자를 대상으로 하고, 개발자용 고급 기능은 설정에서 켤 수 있어요. DeepSeek Harness의 제품 기능과 플러그인 API는 앞으로도 빠르게 바뀌고 발전할 것으로 예상되며, 시간이 지나면서 차츰 안정될 거예요.\n\n오픈 소스이고 재사용과 조합이 가능한 인프라를 바탕으로, 전 세계 사용자, 개발자와 함께 지능의 한계를 탐구해 나가기를 기대해요. 누구나 DeepSeek Harness로 아이디어를 실현하고, 커뮤니티에 참여해 플러그인 생태계를 풍성하게 만들어 주시기를 바라요.",
